//! Built-in copy and record sounds, generated by `scripts/gen-sounds.mjs`.
//! `shutter.wav` (Windows capture sound) is cut from Wikimedia Commons
//! `File:Holga_shuttersound.ogg`, which is in the public domain.

use std::sync::atomic::{AtomicBool, Ordering};

/// macOS's own screenshot sound; played from the system, never bundled.
#[cfg(target_os = "macos")]
#[allow(dead_code)] // used by `app::capture` (Task 5)
const SYSTEM_SHUTTER: &str = "/System/Library/Components/CoreAudio.component/Contents/SharedSupport/SystemSounds/system/Screen Capture.aif";

static RECORDING: AtomicBool = AtomicBool::new(false);

/// While on, copy sounds are muted so they don't end up in the recording.
#[allow(dead_code)] // used by `app::recorder` (Task 7)
pub fn set_recording(on: bool) {
    RECORDING.store(on, Ordering::Relaxed);
}

fn copy_muted() -> bool {
    RECORDING.load(Ordering::Relaxed)
}

pub fn wav(name: &str) -> Option<&'static [u8]> {
    Some(match name {
        "pop" => include_bytes!("../../sounds/pop.wav"),
        "click" => include_bytes!("../../sounds/click.wav"),
        "chime" => include_bytes!("../../sounds/chime.wav"),
        "bubble" => include_bytes!("../../sounds/bubble.wav"),
        "tap" => include_bytes!("../../sounds/tap.wav"),
        "record-start" => include_bytes!("../../sounds/record-start.wav"),
        "record-stop" => include_bytes!("../../sounds/record-stop.wav"),
        "shutter" => include_bytes!("../../sounds/shutter.wav"),
        _ => return None,
    })
}

/// Plays a copy sound, unless a recording is running. Main thread only on macOS (AppKit).
pub fn play(name: &str) {
    if !copy_muted() {
        play_wav(name);
    }
}

/// Plays the record start/stop cue. Main thread only on macOS.
#[allow(dead_code)] // used by `app::recorder` (Task 7)
pub fn play_record(start: bool) {
    play_wav(if start { "record-start" } else { "record-stop" });
}

/// Plays the capture sound: the system screenshot sound, or nothing if it is missing.
/// Main thread only.
#[cfg(target_os = "macos")]
#[allow(dead_code)] // used by `app::capture` (Task 5)
pub fn play_shutter() {
    use objc2::{AnyThread, rc::Retained};
    use objc2_app_kit::NSSound;
    use objc2_foundation::NSString;
    use std::cell::OnceCell;

    // Kept alive like `play_wav`'s sounds; `None` caches a missing file.
    thread_local! {
        static SHUTTER: OnceCell<Option<Retained<NSSound>>> = const { OnceCell::new() };
    }
    SHUTTER.with(|cell| {
        let sound =
            cell.get_or_init(|| NSSound::initWithContentsOfFile_byReference(NSSound::alloc(), &NSString::from_str(SYSTEM_SHUTTER), true));
        if let Some(sound) = sound {
            sound.stop();
            sound.play();
        }
    });
}

#[cfg(windows)]
#[allow(dead_code)] // used by `app::capture` (Task 5)
pub fn play_shutter() {
    play_wav("shutter");
}

#[cfg(target_os = "macos")]
fn play_wav(name: &str) {
    use objc2::{AnyThread, rc::Retained};
    use objc2_app_kit::NSSound;
    use objc2_foundation::NSData;
    use std::{cell::RefCell, collections::HashMap};

    // Keep each NSSound alive so playback isn't cut off when it would be dropped.
    thread_local! {
        static LOADED: RefCell<HashMap<String, Retained<NSSound>>> = RefCell::default();
    }
    let Some(bytes) = wav(name) else { return };
    LOADED.with_borrow_mut(|loaded| {
        if !loaded.contains_key(name) {
            let Some(sound) = NSSound::initWithData(NSSound::alloc(), &NSData::with_bytes(bytes)) else { return };
            loaded.insert(name.to_string(), sound);
        }
        let sound = &loaded[name];
        // Restart if a previous copy's sound is still playing.
        sound.stop();
        sound.play();
    });
}

#[cfg(windows)]
fn play_wav(name: &str) {
    use ::windows::Win32::Media::Audio::{PlaySoundW, SND_ASYNC, SND_MEMORY};
    use ::windows::core::PCWSTR;
    if let Some(bytes) = wav(name) {
        // With SND_MEMORY the "file name" is the whole WAV image, which is 'static here.
        let _ = unsafe { PlaySoundW(PCWSTR(bytes.as_ptr().cast()), None, SND_MEMORY | SND_ASYNC) };
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_sound_is_a_wav() {
        for name in crate::domain::settings::SOUND_NAMES {
            let bytes = wav(name).unwrap_or_else(|| panic!("{name} has no data"));
            assert_eq!(&bytes[0..4], b"RIFF", "{name}");
            assert_eq!(&bytes[8..12], b"WAVE", "{name}");
        }
        assert!(wav("loud").is_none());
    }

    #[test]
    fn record_sounds_are_wavs() {
        for name in ["record-start", "record-stop", "shutter"] {
            let bytes = wav(name).unwrap_or_else(|| panic!("{name} has no data"));
            assert_eq!(&bytes[0..4], b"RIFF", "{name}");
            assert_eq!(&bytes[8..12], b"WAVE", "{name}");
        }
    }

    #[test]
    fn copy_sound_is_muted_while_recording() {
        set_recording(true);
        assert!(copy_muted());
        set_recording(false);
        assert!(!copy_muted());
    }
}
